  var hexToRgb = (hex) => {
    if (typeof hex !== "string") return null;
    const normalized = hex.replace("#", "");
    const fullHex = normalized.length === 3 ? normalized.split("").map((char) => char + char).join("") : normalized;
    if (fullHex.length !== 6) return null;
    const value = Number.parseInt(fullHex, 16);
    if (Number.isNaN(value)) return null;
    return {
      r: value >> 16 & 255,
      g: value >> 8 & 255,
      b: value & 255
    };
  };
  var rgbToHex = ({ r, g, b }) => {
    const toHex = (channel) => Math.max(0, Math.min(255, Math.round(channel))).toString(16).padStart(2, "0");
    return `#${toHex(r)}${toHex(g)}${toHex(b)}`;
  };
  var mixHexColors = (baseHex, mixHex, amount = 0.5) => {
    const base = hexToRgb(baseHex);
    const mix = hexToRgb(mixHex);
    if (!base || !mix) return baseHex;
    const weight = Math.max(0, Math.min(1, amount));
    return rgbToHex({
      r: base.r + (mix.r - base.r) * weight,
      g: base.g + (mix.g - base.g) * weight,
      b: base.b + (mix.b - base.b) * weight
    });
  };
  var hexToRgba = (hex, alpha) => {
    const rgb = hexToRgb(hex);
    if (!rgb) return hex;
    return `rgba(${rgb.r}, ${rgb.g}, ${rgb.b}, ${alpha})`;
  };
